input.command:
cd /run/stage/world && node --input-type=module -e '
import fs from "node:fs";
const n=JSON.parse(fs.readFileSync("night.json"));
const late=[80,40,50,70];
const old=[80,40,70,50];
const eta=n.efficiency, h=n.slotHours;
function dep(plan,lim,eta){const act=lim.map((k,i)=>Math.min(k,plan[i]));const A=n.buses[0],B=n.buses[1];return {act, A:n.buses[0].startKwh+(act[0]+act[1])*h*eta, B:n.buses[1].startKwh+(act[2]+act[3])*h*eta, acA:(act[0]+act[1])*h, acB:(act[2]+act[3])*h};}
console.log("old sheet vs late limits", JSON.stringify(dep(old,late,eta)));
console.log("revised vs late limits", JSON.stringify(dep(late,late,eta)));
for(const s of [0,10,20,30,40]){const b=[40,100-s,50,50+s];const caps=b.map(l=>Math.max(0,Math.min(n.chargerKw,n.siteLimitKw-l)));console.log("s",s,"caps",caps,"totalAC",caps.reduce((a,c)=>a+c,0)*h,"Aac",(caps[0]+caps[1])*h,"Bac",(caps[2]+caps[3])*h);}
for(const e of [0.9,0.85]){const acA=60,acB=60;console.log("eta",e,"A",72+acA*e,"gap",126-(72+acA*e),"B",76+acB*e,"gap",130-(76+acB*e));}
'
